/* Hourly marine and general weather forecasts at each waypoint's expected arrival. */
let waypointSeaSequence=0;
async function updateWaypointSeas(selected,route){const seq=++waypointSeaSequence,entries=selected.arrivals.map((q,i)=>({q,i})).filter(x=>route.p[x.i].selectable!==false);const fetchOne=async ({q,i})=>{let sea='Forecast unavailable',weather='Forecast unavailable';let common={latitude:q.lat.toFixed(3),longitude:q.lon.toFixed(3),timezone:'GMT',forecast_days:'7'},marine=new URLSearchParams({...common,hourly:'wave_height',length_unit:'imperial',cell_selection:'sea'}),air=new URLSearchParams({...common,hourly:'temperature_2m,weather_code,precipitation_probability,wind_speed_10m,wind_gusts_10m,wind_direction_10m',temperature_unit:'fahrenheit',wind_speed_unit:'kn'});const load=async(url)=>{let response=await fetch(url);if(!response.ok)throw Error();let f=await response.json(),h=f.hourly,j=h.time.findIndex(t=>Math.abs(Date.parse(t+'Z')-q.t)<=1800000);return j<0?null:{h,j};};const all=await Promise.allSettled([load('https://marine-api.open-meteo.com/v1/marine?'+marine),load('https://api.open-meteo.com/v1/forecast?'+air)]);if(all[0].status==='fulfilled'&&all[0].value){let {h,j}=all[0].value;if(Number.isFinite(h.wave_height[j]))sea=h.wave_height[j].toFixed(1)+' ft · marine model';}if(all[1].status==='fulfilled'&&all[1].value){let {h,j}=all[1].value,code=h.weather_code[j],temp=h.temperature_2m[j],wind=h.wind_speed_10m[j],gust=h.wind_gusts_10m[j],prob=h.precipitation_probability[j],direction=h.wind_direction_10m[j],dirs=['N','NE','E','SE','S','SW','W','NW'],sky=code===0?'Clear':code===1?'Mostly clear':code===2?'Partly cloudy':code===3?'Overcast':code<=48?'Fog':code<=67?'Rain or drizzle':code<=77?'Snow':code<=82?'Rain showers':code>=95?'Thunderstorms forecast':'Mixed conditions';let bits=[];if(Number.isFinite(code))bits.push(sky);if(Number.isFinite(temp))bits.push(Math.round(temp)+'°F');if(Number.isFinite(wind))bits.push((Number.isFinite(direction)?dirs[Math.round(direction/45)%8]+' ':'')+'wind '+Math.round(wind)+' kt');if(Number.isFinite(gust))bits.push('gusts '+Math.round(gust)+' kt');if(Number.isFinite(prob))bits.push(prob+'% precipitation chance');if(Number.isFinite(code)&&code>=95)bits.push('thunderstorm probability unavailable');if(bits.length)weather=bits.join(' · ');}return {i,sea,weather};};
 for(let start=0;start<entries.length;start+=6){const done=await Promise.all(entries.slice(start,start+6).map(fetchOne));if(seq!==waypointSeaSequence||trip!==selected)return;for(const {i,sea,weather} of done){document.querySelectorAll(`[data-waypoint-sea="${i}"], [data-brief-sea="${i}"]`).forEach(el=>el.textContent=sea);document.querySelectorAll(`[data-waypoint-weather="${i}"], [data-brief-weather="${i}"]`).forEach(el=>el.textContent=weather);}}
}
